    sentences: [{ zh: "明天会更热。", py: "Míngtiān huì gèng rè.", en: "Tomorrow will be even hotter." }, { zh: "这个方法更好。", py: "Zhège fāngfǎ gèng hǎo.", en: "This method is even better." }],
